import React, { useState } from 'react';
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogFooter,
} from '../ui/dialog';
import { Button } from '../ui/button';
import { Input } from '../ui/input';
import { Label } from '../ui/label';
import { Textarea } from '../ui/textarea';
import { Checkbox } from '../ui/checkbox';
import { clientService } from '../../services/clientService';

export const CreateClientModal = ({ isOpen, onClose, onSuccess }) => {
  const [formData, setFormData] = useState({
    company_name: '',
    contact_person: '',
    email: '',
    phone: '',
    address: '',
    industry: '',
    notes: '',
  });
  const [createUser, setCreateUser] = useState(false);
  const [userPassword, setUserPassword] = useState('');
  const [loading, setLoading] = useState(false);

  const handleChange = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    if (createUser && !userPassword) {
      alert('Debe proporcionar una contraseña para el usuario');
      return;
    }

    setLoading(true);

    try {
      const response = await clientService.create({
        ...formData,
        createUser,
        userPassword,
      });

      if (createUser && response.user) {
        alert(
          `Cliente y usuario creados exitosamente\n\n` +
          `Usuario: ${response.user.email}\n` +
          `Contraseña: ${userPassword}\n\n` +
          `Por favor guarde estas credenciales.`
        );
      } else {
        alert('Cliente creado exitosamente');
      }

      onSuccess();
      onClose();
      setFormData({
        company_name: '',
        contact_person: '',
        email: '',
        phone: '',
        address: '',
        industry: '',
        notes: '',
      });
      setCreateUser(false);
      setUserPassword('');
    } catch (error) {
      alert(error.response?.data?.detail || 'Error al crear cliente');
    } finally {
      setLoading(false);
    }
  };

  return (
    <Dialog open={isOpen} onOpenChange={onClose}>
      <DialogContent className="sm:max-w-[600px] max-h-[90vh] overflow-y-auto">
        <DialogHeader>
          <DialogTitle>Crear Nuevo Cliente</DialogTitle>
        </DialogHeader>
        <form onSubmit={handleSubmit}>
          <div className="space-y-4 py-4">
            <div className="grid grid-cols-2 gap-4">
              <div>
                <Label htmlFor="company_name">Nombre de Empresa *</Label>
                <Input
                  id="company_name"
                  name="company_name"
                  value={formData.company_name}
                  onChange={handleChange}
                  required
                  placeholder="Textiles ABC S.A."
                />
              </div>

              <div>
                <Label htmlFor="contact_person">Persona de Contacto *</Label>
                <Input
                  id="contact_person"
                  name="contact_person"
                  value={formData.contact_person}
                  onChange={handleChange}
                  required
                  placeholder="Juan Pérez"
                />
              </div>
            </div>

            <div className="grid grid-cols-2 gap-4">
              <div>
                <Label htmlFor="email">Email *</Label>
                <Input
                  id="email"
                  name="email"
                  type="email"
                  value={formData.email}
                  onChange={handleChange}
                  required
                  placeholder="contacto@empresa.com"
                />
              </div>

              <div>
                <Label htmlFor="phone">Teléfono *</Label>
                <Input
                  id="phone"
                  name="phone"
                  value={formData.phone}
                  onChange={handleChange}
                  required
                  placeholder="+593 99 123 4567"
                />
              </div>
            </div>

            <div>
              <Label htmlFor="address">Dirección *</Label>
              <Input
                id="address"
                name="address"
                value={formData.address}
                onChange={handleChange}
                required
                placeholder="Av. Principal 123, Ciudad"
              />
            </div>

            <div>
              <Label htmlFor="industry">Industria *</Label>
              <Input
                id="industry"
                name="industry"
                value={formData.industry}
                onChange={handleChange}
                required
                placeholder="Textil, Alimentos, Construcción, etc."
              />
            </div>

            <div>
              <Label htmlFor="notes">Notas</Label>
              <Textarea
                id="notes"
                name="notes"
                value={formData.notes}
                onChange={handleChange}
                placeholder="Información adicional..."
                rows={3}
              />
            </div>

            {/* Opción para crear usuario */}
            <div className="border-t pt-4">
              <div className="flex items-center space-x-2">
                <Checkbox
                  id="create_user"
                  checked={createUser}
                  onCheckedChange={setCreateUser}
                />
                <Label htmlFor="create_user" className="cursor-pointer">
                  Crear usuario de acceso para este cliente
                </Label>
              </div>
              <p className="text-xs text-gray-500 mt-1 ml-6">
                Se creará un usuario tipo "Cliente" con acceso de solo lectura
              </p>

              {createUser && (
                <div className="mt-3 ml-6">
                  <Label htmlFor="user_password">Contraseña del Usuario *</Label>
                  <Input
                    id="user_password"
                    type="password"
                    value={userPassword}
                    onChange={(e) => setUserPassword(e.target.value)}
                    placeholder="Contraseña (mínimo 6 caracteres)"
                    minLength={6}
                    className="mt-1"
                  />
                  <p className="text-xs text-gray-500 mt-1">
                    Email de acceso: {formData.email || '(se usará el email del cliente)'}
                  </p>
                </div>
              )}
            </div>
          </div>

          <DialogFooter>
            <Button type="button" variant="outline" onClick={onClose}>
              Cancelar
            </Button>
            <Button type="submit" disabled={loading} className="bg-green-600 hover:bg-green-700">
              {loading ? 'Creando...' : 'Crear Cliente'}
            </Button>
          </DialogFooter>
        </form>
      </DialogContent>
    </Dialog>
  );
};
